export const waterFilmCaptions=Object.freeze([{"start": 0.3, "end": 5.9, "text": "A sunny winter morning on the bridge. The icicle on the lantern begins to drip."}, {"start": 6.3, "end": 11.65, "text": "In this particle model, ice has an open pattern. Energy entering can melt it."}, {"start": 11.65, "end": 15.9, "text": "The same water molecules move past their neighbors. The sample stays at 0 °C while ice melts."}, {"start": 16.3, "end": 22.9, "text": "Melt the ice in a sealed jar on a balance. The balance does not move: same particles, same mass."}, {"start": 23.3, "end": 29.9, "text": "Energy leaves the jar’s water. Its molecules return to the open ice pattern and still vibrate."}, {"start": 30.0, "end": 35.0, "text": "Melting and freezing rearrange the same water molecules. No new substance is made. (Model.)"}].map(Object.freeze));
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(action,label,disabled=false)=>`<button type="button" data-water-film-action="${action}"${disabled?' disabled':''}>${esc(label)}</button>`;
const intro="This is a model of pure water at ordinary pressure, changing slowly. The icicle drips water away; the jar keeps its water. The night particle picture follows the jar. Its 0 °C thermometer is the water sample, not outdoor air.";
const about=["This is a simplified model, not a view through a real microscope or a filmed experiment. Each particle symbol stands for one water molecule. Ice molecules still vibrate; liquid molecules move past neighbors. Their drawn paths, sizes, spacing and speeds are not measurements. Real molecules do not have to retrace these paths or return to their old places when water freezes.", "The icicle loses water as it drips. The jar is a different example that keeps its water inside; energy can still cross. The night particle picture shows the jar's water losing energy to colder surroundings. It reuses the film's molecule symbols for the jar's water; it does not mean water from the icicle went into the jar. Its thermometer represents the water sample, not outdoor air. The 0 °C example assumes pure water at ordinary pressure, changing slowly; it does not show our table's colder or warmer endpoint stages. The jar and balance are an idea, not a weighing we did: no water gets in or out, so the mass stays the same. A real jar and balance can show small changes, for example when water from the air collects on a cold jar. No new substance is made."];

let waterFilmCleanup=null,waterFilmPause=null;
export function pauseWaterFilm(){waterFilmPause?.();}
export function stopWaterFilm(){waterFilmCleanup?.();waterFilmCleanup=null;waterFilmPause=null;}
export function waterFilmEntry(){return `<aside class="phase-film-invitation"><button type="button" data-phase-action="watch">Watch ice change</button><span>Optional silent film · 35 seconds</span><p>The film has 36 molecule symbols; our table has 12. These are two different explanatory drawings. In the film, a ring marks one molecule symbol so you can follow it through each particle picture. It is not the particle you selected here. Your water model will wait.</p></aside>`;}
export function waterFilmPage(){return `<section class="phase-movie" data-water-film-movie><h2>Same water, different arrangements</h2><p>${esc(intro)}</p><p>You can pause or read the whole transcript. Return at any time; your stage, followed particle and open table notes stay where you left them.</p><video controls playsinline muted preload="none" poster="./assets/water-molecules-corrected.jpg" aria-label="Same water, different arrangements, silent corrected film" aria-describedby="water-film-caption"></video><p id="water-film-caption" class="phase-film-caption" data-water-film-caption>Read the complete transcript below at any time.</p><div class="phase-film-controls">${button('play','Play',true)}${button('replay','Replay',true)}${button('retry','Retry loading')}<button type="button" data-phase-action="return">Return to my water model</button></div><p data-water-film-load-status role="status"></p><details data-water-film-transcript><summary>Read the complete film transcript</summary><ol>${waterFilmCaptions.map(c=>`<li>${esc(c.text)}</li>`).join('')}</ol></details><details><summary>About these drawings</summary>${about.map(p=>`<p>${esc(p)}</p>`).join('')}</details><p class="phase-film-credit">Corrected derivative of the original <em>After the Storm</em> film made with Claude Motion. Andika lettering rendered in the picture, SIL Open Font License 1.1. No authoring player or font files included.</p></section>`;}
export function bindWaterFilm(root,live,beforePlay){
 stopWaterFilm();const video=root.querySelector('video'),play=root.querySelector('[data-water-film-action=play]'),replay=root.querySelector('[data-water-film-action=replay]'),retry=root.querySelector('[data-water-film-action=retry]'),status=root.querySelector('[data-water-film-load-status]'),caption=root.querySelector('[data-water-film-caption]');
 let disposed=false,revision=0,playRevision=0,wanted=false,controller=null,source=null,track=null,playTask=null;const off=[];
 const on=(target,event,fn)=>{target.addEventListener(event,fn);off.push(()=>target.removeEventListener(event,fn));};
 const current=()=>!disposed&&live(),active=()=>current()&&!document.hidden;
 const pause=()=>{wanted=false;playRevision++;video.pause();if(current())play.textContent='Play';};waterFilmPause=pause;
 const detach=()=>{video.removeAttribute('src');track?.remove();track=null;video.load();if(source){URL.revokeObjectURL(source);source=null;}};
 const failure=()=>{if(current())status.textContent='The film could not play here. Read the transcript or return to your model.';};
 const updateCaption=()=>{if(current())caption.textContent=(video.ended?waterFilmCaptions.at(-1):waterFilmCaptions.find(c=>video.currentTime>=c.start&&video.currentTime<c.end))?.text||'\u00a0';};
 const requestPlay=()=>{if(!active()||!source)return;wanted=true;const serial=++playRevision,task={serial,revision};playTask=task;try{Promise.resolve(video.play()).then(()=>{if(playTask!==task)return;playTask=null;if(!active()||!wanted||serial!==playRevision||task.revision!==revision)video.pause();}).catch(e=>{if(playTask===task)playTask=null;if(e?.name!=='AbortError'&&current()&&serial===playRevision&&task.revision===revision){wanted=false;failure();}});}catch{playTask=null;wanted=false;failure();}};
 const load=async auto=>{
  if(!current())return;pause();controller?.abort();const rev=++revision;detach();controller=new AbortController();const signal=controller.signal;play.disabled=true;replay.disabled=true;status.textContent='Loading the water film…';wanted=auto&&!matchMedia('(prefers-reduced-motion: reduce)').matches;const ticket=playRevision;
  try{const response=await fetch('./assets/water-molecules-corrected.mp4',{signal});if(!response.ok)throw Error('Unavailable');const blob=await response.blob();if(!current()||rev!==revision)return;
   source=URL.createObjectURL(new Blob([blob],{type:'video/mp4'}));video.muted=true;video.src=source;track=document.createElement('track');track.kind='captions';track.srclang='en';track.label='English';track.src='./assets/water-molecules-corrected.vtt';video.append(track);track.track.mode='hidden';play.disabled=false;replay.disabled=false;status.textContent='';if(wanted&&ticket===playRevision&&active())requestPlay();
  }catch(e){if(current()&&rev===revision){wanted=false;status.textContent='';if(e?.name!=='AbortError')failure();}}
 };
 on(play,'click',()=>{if(!active()||play.disabled)return;if(video.paused)requestPlay();else pause();});on(replay,'click',()=>{if(!active()||replay.disabled)return;video.currentTime=0;requestPlay();});on(retry,'click',()=>{if(current())void load(false);});
 on(video,'play',()=>{if(!active()||(playTask&&(!wanted||playTask.serial!==playRevision||playTask.revision!==revision))){pause();return;}wanted=true;beforePlay();play.textContent='Pause';});on(video,'pause',()=>{wanted=false;playRevision++;if(current())play.textContent='Play';});on(video,'ended',()=>{wanted=false;updateCaption();});on(video,'timeupdate',updateCaption);on(video,'seeked',updateCaption);on(video,'error',failure);
 on(root.querySelector('[data-water-film-transcript]'),'toggle',e=>{if(e.target.open&&current())pause();});on(document,'visibilitychange',()=>{if(document.hidden)pause();});on(window,'pagehide',pause);
 waterFilmCleanup=()=>{disposed=true;wanted=false;revision++;playRevision++;controller?.abort();off.forEach(fn=>fn());video.pause();detach();};void load(true);
}
